import type {
  WasteCompositionGroup,
  WasteCountry,
  WasteRecyclingData,
  WasteTreatmentGroup,
} from '@eco-metrics/shared';

/** The dataset file as generated by `scripts/generate-waste-recycling-data.mjs`. */
export interface WasteRecyclingDataset extends Omit<WasteRecyclingData, 'dataset'> {
  /** Last update of the World Bank files, `YYYY-MM-DD`. */
  lastUpdated: string;
  /** Day the workbook was retrieved, `YYYY-MM-DD`. */
  retrieved: string;
}

const TREATMENT_GROUPS: Record<WasteTreatmentGroup, true> = {
  recycling: true,
  composting: true,
  incineration: true,
  sanitaryLandfill: true,
  otherLandfill: true,
  openDump: true,
  uncollected: true,
  other: true,
};

const COMPOSITION_GROUPS: Record<WasteCompositionGroup, true> = {
  foodOrganic: true,
  paperCardboard: true,
  plastic: true,
  glass: true,
  metal: true,
  other: true,
};

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isNullableNumber(value: unknown): value is number | null {
  return value === null || isNumber(value);
}

function hasNumbers(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return keys.every((key) => isNumber(value[key]));
}

function isGroupedShares(value: unknown, groups: Record<string, true>): boolean {
  if (!isRecord(value)) {
    return false;
  }
  const names = Object.keys(groups);
  return (
    Object.keys(value).length === names.length &&
    names.every((name) => isNullableNumber(value[name])) &&
    names.some((name) => value[name] !== null)
  );
}

function isGrouped(value: unknown, groups: Record<string, true>): boolean {
  return isRecord(value) && isNumber(value.year) && isGroupedShares(value.shares, groups);
}

const GENERATION_NUMBERS = [
  'kgPerPersonPerDay2022',
  'tonnes2022',
  'tonnes2030',
  'tonnes2040',
  'tonnes2050',
] as const;

function isCountry(value: unknown): value is WasteCountry {
  if (!isRecord(value)) {
    return false;
  }
  const { generation, treatment, composition } = value;
  return (
    typeof value.code === 'string' &&
    (value.iso2 === null || typeof value.iso2 === 'string') &&
    typeof value.name === 'string' &&
    isNullableNumber(value.population) &&
    isRecord(generation) &&
    hasNumbers(generation, GENERATION_NUMBERS) &&
    (generation.reportedYear === null || isNumber(generation.reportedYear)) &&
    (treatment === undefined || isGrouped(treatment, TREATMENT_GROUPS)) &&
    (composition === undefined || isGrouped(composition, COMPOSITION_GROUPS))
  );
}

/** Whether a parsed JSON value has the shape of the generated dataset. */
export function isWasteRecyclingDataset(value: unknown): value is WasteRecyclingDataset {
  if (!isRecord(value)) {
    return false;
  }
  const { world, countries } = value;
  if (!isRecord(world) || !isRecord(world.generation) || !isRecord(world.recycling)) {
    return false;
  }

  return (
    typeof value.lastUpdated === 'string' &&
    DATE_PATTERN.test(value.lastUpdated) &&
    typeof value.retrieved === 'string' &&
    DATE_PATTERN.test(value.retrieved) &&
    hasNumbers(world.generation, GENERATION_NUMBERS) &&
    hasNumbers(world.recycling, ['sharePercent', 'countries', 'populationSharePercent']) &&
    Array.isArray(countries) &&
    countries.length > 0 &&
    countries.every(isCountry)
  );
}
